#!/usr/bin/env python3
import os
import sys
import subprocess
import re

class TranslationExtractor:
    def __init__(self, source_files, output_path='translations.cpp'):
        self.source_files = source_files
        self.output_path = output_path
        self.messages = []
        self.XGETTEXT = 'xgettext'

    def extract_translatable_strings(self):
        try:
            xgettext_cmd = [
                self.XGETTEXT,
                '-k_',
                '--from-code=UTF-8',
                '--boost',
                '--c++',
                '-o', 'messages.pot'
            ] + self.source_files

            process = subprocess.Popen(
                xgettext_cmd, 
                stdout=subprocess.PIPE, 
                stderr=subprocess.PIPE
            )
            stdout, stderr = process.communicate()

            if process.returncode != 0:
                raise RuntimeError(f"Translation extraction failed: {stderr.decode()}")

            return self._parse_pot_file('messages.pot')

        except FileNotFoundError:
            print(f"Error: {self.XGETTEXT} utility not found.")
            sys.exit(1)

    def _parse_pot_file(self, filename):
        current_message = {
            'msgid': '',
            'msgstr': '',
            'line_number': ''
        }
        parsed_messages = []

        with open(filename, 'r', encoding='utf-8') as f:
            lines = f.readlines()

        for line in lines:
            line = line.strip()

            if line.startswith('#:'):
                current_message['line_number'] = line.split()[1]

            if line.startswith('msgid '):
                current_message['msgid'] = line[7:-1].strip('"')

            if line.startswith('msgstr '):
                current_message['msgstr'] = line[8:-1].strip('"')

                if current_message['msgid'] and current_message['msgstr']:
                    parsed_messages.append(current_message)
                    current_message = {
                        'msgid': '',
                        'msgstr': '',
                        'line_number': ''
                    }

        return parsed_messages

    def _sanitize_string(self, text):
        return text.replace('"', '\\"').replace('\n', '\\n')

    def generate_translation_header(self):
        messages = self.extract_translatable_strings()

        with open(self.output_path, 'w', encoding='utf-8') as out_file:
            out_file.write("#ifndef TRANSLATION_H\n")
            out_file.write("#define TRANSLATION_H\n\n")
            out_file.write("#include <QObject>\n\n")
            out_file.write("namespace Translations {\n")
            out_file.write("    inline const char* translate(const char* context, const char* source) {\n")
            out_file.write("        return QObject::tr(source).toUtf8().constData();\n")
            out_file.write("    }\n\n")

            for msg in sorted(messages, key=lambda x: x['msgid']):
                sanitized_msgid = self._sanitize_string(msg['msgid'])
                out_file.write(f"    // Line {msg['line_number']}\n")
                out_file.write(f"    #define TR_{sanitized_msgid.upper().replace(' ', '_')} \\\n")
                out_file.write(f'        translate("Context", "{sanitized_msgid}")\n\n')

            out_file.write("}\n")
            out_file.write("#endif // TRANSLATION_H\n")

        print(f"Translation header generated: {self.output_path}")

    def cleanup(self):
        for temp_file in ['messages.pot']:
            if os.path.exists(temp_file):
                os.remove(temp_file)

def main():
    source_files = [
        'src/main.cpp',
        'src/wallet.cpp',
        'src/ui/dialogs.cpp'
    ]

    translator = TranslationExtractor(source_files)
    try:
        translator.generate_translation_header()
    except Exception as e:
        print(f"Translation generation error: {e}")
    finally:
        translator.cleanup()

if __name__ == '__main__':
    main()

from odoo.tests.common import HttpCase
from odoo.exceptions import ValidationError, UserError
from odoo import api, fields, models

class AccountingTestCase(HttpCase):
    def setUp(self):
        super().setUp()
        self.company = self.env.ref('base.main_company')
        self.accounting_env = self.env['account.account']
        self.move_env = self.env['account.move']
        self.property_env = self.env['ir.property']

        # Check if accounting chart is configured
        chart_template = self.env.ref('account.chart_template_generic', raise_if_not_found=False)
        if not chart_template:
            self.skipTest("No accounting chart template configured")

        # Validate basic accounting setup
        self._validate_accounting_configuration()

    def _validate_accounting_configuration(self):
        """Validate basic accounting environment requirements"""
        try:
            # Check company accounting configuration
            if not self.company.chart_template_id:
                self.skipTest("Company lacks accounting chart template")

            # Verify journal existence
            journals = self.env['account.journal'].search([('company_id', '=', self.company.id)])
            if not journals:
                self.skipTest("No accounting journals configured")
        except Exception as e:
            self.fail(f"Accounting configuration validation failed: {str(e)}")

    def ensure_account_property(self, field_name, model, value):
        """Dynamically create or validate account-related properties"""
        try:
            field = self.env['ir.model.fields'].search([
                ('name', '=', field_name),
                ('model', '=', model)
            ], limit=1)

            if not field:
                raise ValidationError(f"Field {field_name} not found in {model}")

            existing_property = self.property_env.search([
                ('name', '=', field_name),
                ('company_id', '=', self.company.id)
            ])

            if not existing_property:
                self.property_env.create({
                    'name': field_name,
                    'company_id': self.company.id,
                    'fields_id': field.id,
                    'value': value
                })
        except Exception as e:
            self.fail(f"Property setup failed: {str(e)}")

    def check_complete_move(self, move, expected_lines=None):
        """Validate journal entry completeness"""
        if not move:
            self.fail("Journal move cannot be empty")

        # Verify move state and total balance
        self.assertTrue(move.state == 'posted', "Move must be posted")
        self.assertAlmostEqual(sum(move.line_ids.mapped('debit')), 
                               sum(move.line_ids.mapped('credit')), 
                               msg="Move lines must balance")

        if expected_lines:
            actual_lines = move.line_ids
            self.assertEqual(len(actual_lines), len(expected_lines), 
                             "Number of move lines does not match expected")

            for expected, actual in zip(expected_lines, actual_lines):
                self.assertEqual(expected.get('account_id'), actual.account_id.id)
                self.assertAlmostEqual(expected.get('debit', 0), actual.debit)
                self.assertAlmostEqual(expected.get('credit', 0), actual.credit)

import random
import sys
import urllib.request

class PythonSyntaxLearner:
    PHRASES = {
        'class': [
            'class {noun}_class:\n    def __init__(self, {parameter}):\n        self.{parameter} = {parameter}',
            'Create a class named {noun}_class with an initialization method'
        ],
        'method': [
            'def {verb}_method(self, {parameter}):\n    return {parameter} * 2',
            'Define a method that takes a parameter and performs a simple operation'
        ],
        'inheritance': [
            'class {noun}_child({noun}_parent):\n    def __init__(self, {parameter}):\n        super().__init__({parameter})',
            'Create a child class that inherits from a parent class'
        ]
    }

    def __init__(self, words_file='words.txt'):
        self.WORDS = self.load_words(words_file)
        self.PHRASE_FIRST = random.choice([True, False])

    def load_words(self, file_path):
        try:
            with open(file_path, 'r') as f:
                return [word.strip() for word in f.readlines()]
        except FileNotFoundError:
            try:
                url = 'https://example.com/words.txt'
                response = urllib.request.urlopen(url)
                return [word.decode('utf-8').strip() for word in response.readlines()]
            except:
                return ['sample', 'random', 'dynamic', 'learning', 'python']

    def generate_random_word(self, word_type='noun'):
        return random.choice(self.WORDS)

    def convert(self, phrase_type='class'):
        template_code, template_explanation = self.PHRASES.get(phrase_type, self.PHRASES['class'])

        replacements = {
            '{noun}': self.generate_random_word('noun'),
            '{parameter}': self.generate_random_word('parameter'),
            '{verb}': self.generate_random_word('verb')
        }

        generated_code = template_code.format(**replacements)
        generated_explanation = template_explanation.format(**replacements)

        return generated_code, generated_explanation

    def quiz_mode(self):
        print("Python OOP Learning Quiz")
        score = 0
        total_questions = 3

        for _ in range(total_questions):
            code, explanation = self.convert()

            if self.PHRASE_FIRST:
                print("\nExplanation:", explanation)
                user_guess = input("Translate this explanation to Python code: ")
                print("\nGenerated Code:\n", code)
            else:
                print("\nCode:\n", code)
                user_guess = input("Explain what this code does: ")
                print("\nExplanation:", explanation)

            if user_guess.strip().lower() in explanation.lower() or \
               user_guess.strip() in code:
                print("✓ Correct!")
                score += 1
            else:
                print("✗ Incorrect")

        print(f"\nQuiz Complete! Score: {score}/{total_questions}")

    def run(self, mode='quiz'):
        if mode == 'quiz':
            self.quiz_mode()
        else:
            code, explanation = self.convert()
            print("Generated Code:\n", code)
            print("\nExplanation:", explanation)

def main():
    learner = PythonSyntaxLearner()

    if len(sys.argv) > 1:
        learner.run(sys.argv[1])
    else:
        learner.run()

if __name__ == "__main__":
    main()

