import logging
import socket
import ssl
import time
import urllib.parse

class StreamHandler:
    def __init__(self, logger=None):
        self.logger = logger or logging.getLogger(__name__)
        self.start_time = None
        self.rtt = None

    def connection_made(self, transport):
        self.start_time = time.time()
        self.logger.debug("Connection established")

    def connection_lost(self, exc):
        if exc:
            self.logger.error(f"Connection lost: {exc}")

class HttpMessage:
    def __init__(self):
        self.headers = {}
        self.body = b''
        self.status_code = None

    def add_header(self, key, value):
        self.headers[key.lower()] = value

    def parse_headers(self, header_data):
        lines = header_data.split('\r\n')
        status_line = lines[0]
        self.status_code = int(status_line.split()[1])

        for line in lines[1:]:
            if line:
                key, value = line.split(':', 1)
                self.add_header(key.strip(), value.strip())

class HttpClientStream(StreamHandler):
    def __init__(self, uri, method='GET', headers=None):
        super().__init__()
        self.uri = uri
        self.method = method
        self.headers = headers or {}
        self.response = HttpMessage()
        self.transport = None
        self.buffer = b''

    def connection_made(self, transport):
        super().connection_made(transport)
        self.transport = transport
        request = self._build_request()
        transport.write(request.encode('utf-8'))

    def data_received(self, data):
        self.buffer += data
        try:
            headers_end = self.buffer.index(b'\r\n\r\n')
            headers_data = self.buffer[:headers_end].decode('utf-8')
            self.response.parse_headers(headers_data)
            self.response.body = self.buffer[headers_end+4:]
        except ValueError:
            pass

    def _build_request(self):
        parsed_uri = urllib.parse.urlparse(self.uri)
        host_header = parsed_uri.netloc
        request_line = f"{self.method} {parsed_uri.path or '/'} HTTP/1.1\r\n"
        headers = [
            f"Host: {host_header}",
            "Connection: close",
            "User-Agent: NeuBot HTTP Client"
        ]

        for key, value in self.headers.items():
            headers.append(f"{key}: {value}")

        return request_line + '\r\n'.join(headers) + '\r\n\r\n'

class HttpClient:
    def __init__(self, logger=None):
        self.logger = logger or logging.getLogger(__name__)

    def connect_uri(self, uri, method='GET', headers=None, timeout=10):
        parsed_uri = urllib.parse.urlparse(uri)
        host = parsed_uri.hostname
        port = parsed_uri.port or (443 if parsed_uri.scheme == 'https' else 80)

        stream = HttpClientStream(uri, method, headers)

        try:
            if parsed_uri.scheme == 'https':
                context = ssl.create_default_context()
                sock = socket.create_connection((host, port), timeout=timeout)
                secure_sock = context.wrap_socket(sock, server_hostname=host)
                stream.connection_made(secure_sock)
            else:
                sock = socket.create_connection((host, port), timeout=timeout)
                stream.connection_made(sock)

            return stream

        except Exception as e:
            self.logger.error(f"Connection error: {e}")
            return None

def main():
    logging.basicConfig(level=logging.INFO)
    client = HttpClient()
    stream = client.connect_uri('https://www.example.com')

    if stream:
        time.sleep(2)  # Simulating connection and data retrieval
        print(f"Status Code: {stream.response.status_code}")
        print(f"Headers: {stream.response.headers}")
        print(f"Body Length: {len(stream.response.body)}")

if __name__ == '__main__':
    main()

import pickle
import socket
import os
import json
import uuid

class DaemonCommunicator:
    def __init__(self, host='localhost', port=9999, root_dir=None):
        self.host = host
        self.port = port
        self.root_dir = root_dir or os.getcwd()
        self._validate_root_directory()

    def _validate_root_directory(self):
        if not os.path.exists(self.root_dir):
            raise ValueError(f"Root directory {self.root_dir} does not exist")

    def connect_socket(self):
        try:
            client = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            client.connect((self.host, self.port))
            return client
        except ConnectionRefusedError:
            raise RuntimeError("Could not connect to daemon process")

    def receive_data(self, client):
        try:
            response_length = int.from_bytes(client.recv(4), byteorder='big')
            raw_response = client.recv(response_length)
            return pickle.loads(raw_response)
        except Exception as e:
            raise RuntimeError(f"Error receiving data: {e}")

    def process_response(self, response):
        if response.get('status') == 'error':
            raise RuntimeError(response.get('message', 'Unknown error'))
        return response.get('payload')

    def command_factory(self, command_type):
        def dynamic_command(**kwargs):
            body = {
                'command_id': str(uuid.uuid4()),
                'type': command_type,
                'payload': kwargs,
                'root_dir': self.root_dir
            }

            client = self.connect_socket()
            try:
                serialized_payload = pickle.dumps(body)
                payload_length = len(serialized_payload).to_bytes(4, byteorder='big')

                client.send(payload_length)
                client.send(serialized_payload)

                response = self.receive_data(client)
                return self.process_response(response)
            except Exception as e:
                raise RuntimeError(f"Command execution failed: {e}")
            finally:
                client.close()

        return dynamic_command

    def print_command_factory(self, template):
        def print_command(**kwargs):
            formatted_message = template.format(**kwargs)
            return self.command_factory('print')(message=formatted_message)

        return print_command

    def generate_command_set(self, commands_config):
        command_set = {}
        for cmd_name, cmd_details in commands_config.items():
            if cmd_details.get('type') == 'print':
                command_set[cmd_name] = self.print_command_factory(cmd_details.get('template', ''))
            else:
                command_set[cmd_name] = self.command_factory(cmd_details.get('type'))
        return command_set

def main():
    communicator = DaemonCommunicator(root_dir='/path/to/daemon/root')

    commands_config = {
        'log_info': {'type': 'print', 'template': 'INFO: {message}'},
        'execute_task': {'type': 'task_execution'},
        'retrieve_data': {'type': 'data_retrieval'}
    }

    daemon_commands = communicator.generate_command_set(commands_config)

    try:
        # Example usage of dynamically generated commands
        daemon_commands['log_info'](message="Daemon process initialized")
        result = daemon_commands['execute_task'](task_id='123', parameters={'key': 'value'})
        data = daemon_commands['retrieve_data'](query_params={'filter': 'recent'})
    except Exception as e:
        print(f"Daemon communication error: {e}")

if __name__ == '__main__':
    main()

from django.db import models
from django.contrib.contenttypes.models import ContentType
from django.contrib.contenttypes.fields import GenericForeignKey
from django.db.models import Count, Q

class ModelTagManager(models.Manager):
    def get_queryset(self):
        return super().get_queryset()

    def related(self, model_instance):
        """
        Find tags related to a specific model instance
        """
        content_type = ContentType.objects.get_for_model(model_instance.__class__)
        return self.filter(
            modeltaggeditem__content_type=content_type,
            modeltaggeditem__object_id=model_instance.pk
        ).distinct()

    def usage(self, model_cls=None):
        """
        Retrieve tag usage statistics across models
        """
        queryset = self.annotate(usage_count=Count('modeltaggeditem'))

        if model_cls is not None:
            content_type = ContentType.objects.get_for_model(model_cls)
            queryset = queryset.filter(
                modeltaggeditem__content_type=content_type
            )

        return queryset.order_by('-usage_count')

    def related_to(self, tag_list):
        """
        Find tags related to a list of tags
        """
        return self.filter(
            modeltaggeditem__tag__in=tag_list
        ).exclude(
            pk__in=tag_list
        ).distinct()

    def with_all(self, tag_list, model_cls=None):
        """
        Filter model instances with all specified tags
        """
        if model_cls is None:
            raise ValueError("Model class must be specified")

        content_type = ContentType.objects.get_for_model(model_cls)

        tagged_items = ModelTaggedItem.objects.filter(
            content_type=content_type,
            tag__in=tag_list
        )

        tag_count = len(tag_list)
        object_ids = tagged_items.values('object_id').annotate(
            tag_count=Count('tag')
        ).filter(tag_count=tag_count).values('object_id')

        return model_cls.objects.filter(pk__in=object_ids)

    def with_any(self, tag_list, model_cls=None):
        """
        Filter model instances with any of the specified tags
        """
        if model_cls is None:
            raise ValueError("Model class must be specified")

        content_type = ContentType.objects.get_for_model(model_cls)

        tagged_items = ModelTaggedItem.objects.filter(
            content_type=content_type,
            tag__in=tag_list
        )

        object_ids = tagged_items.values_list('object_id', flat=True).distinct()

        return model_cls.objects.filter(pk__in=object_ids)

class ModelTaggedItemManager(models.Manager):
    def get_by_model(self, model_cls):
        """
        Retrieve tagged items for a specific model
        """
        content_type = ContentType.objects.get_for_model(model_cls)
        return self.filter(content_type=content_type)

class TagDescriptor:
    def __init__(self, through_model):
        self.through_model = through_model

    def __get__(self, instance, owner):
        if instance is None:
            return self

        content_type = ContentType.objects.get_for_model(owner)
        return self.through_model.objects.filter(
            content_type=content_type,
            object_id=instance.pk
        )

    def __set__(self, instance, value):
        content_type = ContentType.objects.get_for_model(instance.__class__)

        # Clear existing tags
        self.through_model.objects.filter(
            content_type=content_type,
            object_id=instance.pk
        ).delete()

        # Add new tags
        for tag in value:
            self.through_model.objects.create(
                tag=tag,
                content_type=content_type,
                object_id=instance.pk
            )

class Tag(models.Model):
    name = models.CharField(max_length=50, unique=True)
    objects = ModelTagManager()

    def __str__(self):
        return self.name

class ModelTaggedItem(models.Model):
    tag = models.ForeignKey(Tag, on_delete=models.CASCADE)
    content_type = models.ForeignKey(ContentType, on_delete=models.CASCADE)
    object_id = models.PositiveIntegerField()
    content_object = GenericForeignKey('content_type', 'object_id')
    objects = ModelTaggedItemManager()

    class Meta:
        unique_together = ('tag', 'content_type', 'object_id')

