from openerp.osv import osv, fields
from openerp.tools.translate import _

class res_partner(osv.osv):
    _inherit = 'res.partner'

    def _check_unique_ref(self, cr, uid, ids, context=None):
        """
        Validate unique reference constraint for partners
        """
        for partner in self.browse(cr, uid, ids, context=context):
            if partner.ref:
                ref_count = self.search_count(
                    cr, uid, 
                    [('ref', '=', partner.ref), ('id', '!=', partner.id)], 
                    context=context
                )
                if ref_count > 0:
                    return False
        return True

    def _generate_partner_ref(self, cr, uid, context=None):
        """
        Generate unique reference code using sequence
        """
        sequence_obj = self.pool.get('ir.sequence')
        return sequence_obj.get(cr, uid, 'res.partner.ref', context=context)

    def create(self, cr, uid, vals, context=None):
        """
        Override create method to handle reference generation
        """
        if context is None:
            context = {}

        # Generate reference if not provided
        if not vals.get('ref'):
            vals['ref'] = self._generate_partner_ref(cr, uid, context)

        # Ensure reference uniqueness
        partner_id = super(res_partner, self).create(cr, uid, vals, context)

        return partner_id

    def write(self, cr, uid, ids, vals, context=None):
        """
        Override write method to validate reference modifications
        """
        if context is None:
            context = {}

        # Generate reference if not provided during write
        if not vals.get('ref'):
            for partner_id in ids:
                partner = self.browse(cr, uid, partner_id, context=context)
                if not partner.ref:
                    vals['ref'] = self._generate_partner_ref(cr, uid, context)

        # Update partners
        result = super(res_partner, self).write(cr, uid, ids, vals, context)
        return result

    def copy(self, cr, uid, obj_id, default=None, context=None):
        """
        Override copy method to generate new reference
        """
        if context is None:
            context = {}

        if default is None:
            default = {}

        # Generate new reference for copied record
        default['ref'] = self._generate_partner_ref(cr, uid, context)

        # Perform standard copy operation
        return super(res_partner, self).copy(cr, uid, obj_id, default, context)

    _constraints = [
        (_check_unique_ref, 
         'Error: Partner reference must be unique!', 
         ['ref'])
    ]

    _sql_constraints = [
        ('unique_partner_ref', 
         'UNIQUE(ref)', 
         'Partner reference must be unique across the system!')
    ]

res_partner()

class RegisterHandler:
    _registerClasses = [
        # General Purpose Registers
        ['RAX', 'EAX', 'AX', 'AH', 'AL'],
        ['RBX', 'EBX', 'BX', 'BH', 'BL'],
        ['RCX', 'ECX', 'CX', 'CH', 'CL'],
        ['RDX', 'EDX', 'DX', 'DH', 'DL'],

        # Segment Registers
        ['CS', 'DS', 'ES', 'FS', 'GS', 'SS'],

        # Stack and Base Pointer Registers
        ['RSP', 'ESP', 'SP', 'SPL'],
        ['RBP', 'EBP', 'BP', 'BPL'],

        # Index Registers
        ['RSI', 'ESI', 'SI', 'SIL'],
        ['RDI', 'EDI', 'DI', 'DIL'],

        # Extended Registers
        ['R8', 'R8D', 'R8W', 'R8B'],
        ['R9', 'R9D', 'R9W', 'R9B'],
        ['R10', 'R10D', 'R10W', 'R10B'],

        # Control Registers
        ['CR0', 'CR1', 'CR2', 'CR3', 'CR4']
    ]

    @classmethod
    def get_reg_class(cls, reg):
        """
        Find the register class for a given register name
        """
        reg = reg.upper()
        for reg_class in cls._registerClasses:
            if reg in reg_class:
                return reg_class
        return None

    @classmethod
    def get_reg_by_size(cls, size):
        """
        Retrieve registers of a specific size
        """
        size_map = {
            8: ['AL', 'BL', 'CL', 'DL', 'SIL', 'DIL', 'R8B', 'R9B', 'R10B'],
            16: ['AX', 'BX', 'CX', 'DX', 'SP', 'BP', 'SI', 'DI', 'R8W', 'R9W', 'R10W'],
            32: ['EAX', 'EBX', 'ECX', 'EDX', 'ESP', 'EBP', 'ESI', 'EDI', 'R8D', 'R9D', 'R10D'],
            64: ['RAX', 'RBX', 'RCX', 'RDX', 'RSP', 'RBP', 'RSI', 'RDI', 'R8', 'R9', 'R10']
        }
        return size_map.get(size, [])

    @classmethod
    def get_size_by_reg(cls, reg):
        """
        Determine register size based on prefix
        """
        reg = reg.upper()
        size_prefixes = {
            'R': 64,
            'E': 32,
            None: 16 if len(reg) == 2 else 8
        }

        prefix = reg[0] if len(reg) > 2 else None
        return size_prefixes.get(prefix, 8)

    @classmethod
    def get_reg_class_lst(cls, reg_class):
        """
        Return the entire register class list
        """
        for group in cls._registerClasses:
            if reg_class.upper() in [r.upper() for r in group]:
                return group
        return None

    @classmethod
    def normalize_reg_name(cls, reg):
        """
        Normalize register name for consistent lookup
        """
        return reg.upper().strip()

    @classmethod
    def cross_reference_register(cls, reg):
        """
        Cross-reference register across different bit-width representations
        """
        reg = cls.normalize_reg_name(reg)
        reg_class = cls.get_reg_class(reg)

        if not reg_class:
            return None

        return {
            'class': reg_class,
            'size': cls.get_size_by_reg(reg),
            'variants': [r for r in reg_class if r != reg]
        }

    @classmethod
    def validate_register(cls, reg):
        """
        Validate if register exists in known register classes
        """
        return cls.get_reg_class(reg) is not None

