import os
from buildbot.steps.shell import ShellCommand
from buildbot.process.buildstep import BuildStep
from buildbot.plugins import steps, util
from distutils.version import LooseVersion

class BuildImages(ShellCommand):
    def __init__(self, **kwargs):
        self.layer_versions = {
            'yocto-bsp': None,
            'core': None
        }
        self.build_configs = {
            'machine': kwargs.get('machine', 'generic'),
            'image_type': kwargs.get('image_type', 'core-image-minimal'),
            'layers': kwargs.get('layers', []),
            'build_flags': kwargs.get('build_flags', [])
        }

        self.validate_configuration()
        self.prepare_build_environment()

        super().__init__(**kwargs)

    def validate_configuration(self):
        """Validate and sanitize build configuration"""
        if not self.build_configs['machine']:
            raise ValueError("Machine configuration is required")

        self.layer_versions['yocto-bsp'] = self._detect_layer_version('yocto-bsp')
        self.layer_versions['core'] = self._detect_layer_version('core')

    def _detect_layer_version(self, layer_name):
        """Dynamically detect Yocto layer version"""
        version_file_path = os.path.join(layer_name, 'conf', 'layer.conf')
        try:
            with open(version_file_path, 'r') as version_file:
                for line in version_file:
                    if 'LAYERVERSION' in line:
                        return LooseVersion(line.split('=')[1].strip())
        except FileNotFoundError:
            return None

    def prepare_build_environment(self):
        """Set up build environment with version-specific configurations"""
        self.build_configs['env'] = {
            'MACHINE': self.build_configs['machine'],
            'IMAGE_FSTYPES': self._determine_image_formats()
        }

        # Conditionally modify configurations based on layer versions
        if (self.layer_versions['core'] and 
            self.layer_versions['core'] < LooseVersion('2.5')):
            self.build_configs['image_type'] = 'core-image-base'

    def _determine_image_formats(self):
        """Dynamically determine appropriate image formats"""
        machine_specifics = {
            'intel-x86': ['wic', 'iso'],
            'qemu': ['ext4', 'vmdk'],
            'default': ['ext4']
        }
        return ' '.join(machine_specifics.get(
            self.build_configs['machine'], 
            machine_specifics['default']
        ))

    def start(self, remote_command=None):
        """Execute build process with dynamic configuration"""
        bitbake_command = [
            'bitbake',
            self.build_configs['image_type']
        ] + self.build_configs.get('build_flags', [])

        # Implement conditional build skipping
        if self._should_skip_build():
            return util.SUCCESS

        self.addCompleteLog('build_config', str(self.build_configs))
        return super().start(bitbake_command)

    def _should_skip_build(self):
        """Determine whether to skip build based on configuration"""
        skip_conditions = [
            (self.build_configs['machine'] == 'unsupported', 
             "Unsupported machine configuration"),
            (not self.layer_versions['core'], 
             "Missing core layer version")
        ]

        for condition, reason in skip_conditions:
            if condition:
                self.addCompleteLog('skip_reason', reason)
                return True

        return False

    def describe(self, done=False):
        """Provide descriptive information about the build step"""
        description = [
            f"Build {self.build_configs['image_type']} for {self.build_configs['machine']}"
        ]

        if done:
            description.append("Completed")

        return description

