import unittest

def max_difference(numbers):
    if not numbers:
        return None
    return max(numbers) - min(numbers)

class TestMaxDifference(unittest.TestCase):
    TESTS = {
        'Level_1': [
            {
                'input': [1, 2, 3, 4, 5],
                'expected': 4,
                'explanation': 'Simple ascending sequence'
            },
            {
                'input': [5, 3, 1, 4, 2],
                'expected': 4,
                'explanation': 'Unordered sequence'
            },
            {
                'input': [-5, -2, -8, -1],
                'expected': 7,
                'explanation': 'Negative numbers'
            },
            {
                'input': [0, 0, 0, 0],
                'expected': 0,
                'explanation': 'All identical values'
            },
            {
                'input': [1.5, 2.7, 3.2, 4.1],
                'expected': 2.6,
                'explanation': 'Floating point numbers'
            },
            {
                'input': [],
                'expected': None,
                'explanation': 'Empty list'
            },
            {
                'input': [-10, 10],
                'expected': 20,
                'explanation': 'Mixed positive and negative values'
            },
            {
                'input': [100],
                'expected': 0,
                'explanation': 'Single element list'
            },
            {
                'input': [0.5, -0.5, 1.5, -1.5],
                'expected': 3,
                'explanation': 'Mixed floating point values'
            },
            {
                'input': [10, 5, 8, 12, 3],
                'expected': 9,
                'explanation': 'Random sequence with larger range'
            }
        ]
    }

    def test_max_difference(self):
        for test_case in self.TESTS['Level_1']:
            with self.subTest(input=test_case['input'], 
                              expected=test_case['expected'], 
                              explanation=test_case['explanation']):
                result = max_difference(test_case['input'])
                self.assertEqual(result, test_case['expected'], 
                                 f"Failed for {test_case['explanation']}")

    def test_edge_cases(self):
        # Additional specific edge case testing
        self.assertIsNone(max_difference([]), "Empty list should return None")
        self.assertEqual(max_difference([42]), 0, "Single element list should return 0")

    def test_type_handling(self):
        # Type conversion and handling tests
        self.assertEqual(max_difference([1, 2, 3]), 2, "Basic integer list")
        self.assertAlmostEqual(max_difference([1.1, 2.2, 3.3]), 2.2, 
                               msg="Floating point precision check")

def run_tests():
    unittest.main(argv=[''], verbosity=2, exit=False)

if __name__ == '__main__':
    run_tests()

from django.db import models
from django.contrib.auth.models import User
from rest_framework import viewsets, serializers, permissions, status
from rest_framework.decorators import action
from rest_framework.response import Response

class TicketStatus(models.TextChoices):
    DRAFT = 'DRAFT', 'Draft'
    PENDING = 'PENDING', 'Pending Approval'
    APPROVED = 'APPROVED', 'Approved'
    REJECTED = 'REJECTED', 'Rejected'
    CLOSED = 'CLOSED', 'Closed'

class Ticket(models.Model):
    title = models.CharField(max_length=255)
    description = models.TextField()
    creator = models.ForeignKey(User, related_name='created_tickets', on_delete=models.CASCADE)
    assignee = models.ForeignKey(User, related_name='assigned_tickets', null=True, on_delete=models.SET_NULL)
    status = models.CharField(max_length=20, choices=TicketStatus.choices, default=TicketStatus.DRAFT)
    created_at = models.DateTimeField(auto_now_add=True)
    updated_at = models.DateTimeField(auto_now=True)

    def can_transition(self, user, from_status, to_status):
        transitions = {
            (TicketStatus.DRAFT, TicketStatus.PENDING): lambda u: u == self.creator,
            (TicketStatus.PENDING, TicketStatus.APPROVED): lambda u: u.is_staff,
            (TicketStatus.PENDING, TicketStatus.REJECTED): lambda u: u.is_staff,
            (TicketStatus.APPROVED, TicketStatus.CLOSED): lambda u: u.is_staff or u == self.creator
        }
        return transitions.get((from_status, to_status), lambda u: False)(user)

class TicketPermissions(permissions.BasePermission):
    def has_permission(self, request, view):
        if view.action in ['list', 'retrieve']:
            return True
        return request.user.is_authenticated

    def has_object_permission(self, request, view, obj):
        if view.action in ['retrieve', 'update', 'partial_update']:
            return obj.creator == request.user or request.user.is_staff
        return True

class TicketDisplaySerializer(serializers.ModelSerializer):
    class Meta:
        model = Ticket
        fields = ['id', 'title', 'description', 'status', 'created_at', 'creator']

class TicketCreateSerializer(serializers.ModelSerializer):
    class Meta:
        model = Ticket
        fields = ['title', 'description']

    def create(self, validated_data):
        validated_data['creator'] = self.context['request'].user
        return super().create(validated_data)

class TicketApproveSerializer(serializers.Serializer):
    def validate(self, attrs):
        ticket = self.context['ticket']
        user = self.context['request'].user
        if not ticket.can_transition(user, ticket.status, TicketStatus.APPROVED):
            raise serializers.ValidationError("Not authorized to approve this ticket")
        return attrs

class TicketViewSet(viewsets.ModelViewSet):
    queryset = Ticket.objects.all()
    permission_classes = [TicketPermissions]

    def get_serializer_class(self):
        if self.action == 'create':
            return TicketCreateSerializer
        return TicketDisplaySerializer

    def get_queryset(self):
        user = self.request.user
        if user.is_staff:
            return Ticket.objects.all()
        return Ticket.objects.filter(creator=user) | Ticket.objects.filter(assignee=user)

    @action(detail=True, methods=['POST'])
    def open(self, request, pk=None):
        ticket = self.get_object()
        if ticket.can_transition(request.user, ticket.status, TicketStatus.PENDING):
            ticket.status = TicketStatus.PENDING
            ticket.save()
            return Response({'status': 'ticket opened'})
        return Response(status=status.HTTP_403_FORBIDDEN)

    @action(detail=True, methods=['POST'])
    def approve(self, request, pk=None):
        ticket = self.get_object()
        serializer = TicketApproveSerializer(data=request.data, context={'ticket': ticket, 'request': request})

        if serializer.is_valid():
            ticket.status = TicketStatus.APPROVED
            ticket.save()
            return Response({'status': 'ticket approved'})
        return Response(serializer.errors, status=status.HTTP_400_BAD_REQUEST)

import sys
import subprocess
import time
import os
import signal
import platform

class StarCraftBotTestRunner:
    def __init__(self, script_path, max_retries=3, timeout_duration=300):
        self.script_path = script_path
        self.max_retries = max_retries
        self.timeout_duration = timeout_duration
        self.current_retry = 0
        self.system_platform = platform.system()

    def _detect_line_break(self, output):
        """Dynamically detect line break formatting."""
        if b'\r\n' in output:
            return b'\r\n'
        elif b'\n' in output:
            return b'\n'
        return b'\n'

    def _terminate_process(self, process):
        """Cross-platform process termination."""
        try:
            if self.system_platform == 'Windows':
                process.terminate()
                time.sleep(0.5)
                if process.poll() is None:
                    process.kill()
            else:
                os.killpg(os.getpgid(process.pid), signal.SIGTERM)
        except Exception as e:
            print(f"Termination error: {e}")

    def run_bot_test(self):
        """Execute StarCraft II bot script with retry and timeout management."""
        while self.current_retry < self.max_retries:
            start_time = time.time()
            process = None
            stdout_data = b''
            stderr_data = b''
            exit_code = None

            try:
                process = subprocess.Popen(
                    [sys.executable, self.script_path],
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    preexec_fn=os.setsid if self.system_platform != 'Windows' else None,
                    universal_newlines=False
                )

                while process.poll() is None:
                    current_time = time.time()
                    elapsed_time = current_time - start_time

                    if elapsed_time > self.timeout_duration:
                        self._terminate_process(process)
                        raise subprocess.TimeoutExpired(self.script_path, self.timeout_duration)

                    time.sleep(0.1)

                stdout_data, stderr_data = process.communicate()
                exit_code = process.returncode

                if exit_code == 0:
                    print(f"Bot test successful on attempt {self.current_retry + 1}")
                    break
                else:
                    print(f"Bot test failed with exit code {exit_code}")

            except subprocess.TimeoutExpired:
                print(f"Timeout occurred on attempt {self.current_retry + 1}")
                self._terminate_process(process)
                exit_code = -2
            except Exception as e:
                print(f"Unexpected error: {e}")
                exit_code = -1
            finally:
                if stdout_data or stderr_data:
                    line_break = self._detect_line_break(stdout_data or stderr_data)
                    if stdout_data:
                        print("Standard Output:")
                        for line in stdout_data.split(line_break):
                            print(line.decode('utf-8', errors='replace'))
                    if stderr_data:
                        print("Standard Error:")
                        for line in stderr_data.split(line_break):
                            print(line.decode('utf-8', errors='replace'))

                self.current_retry += 1

        return exit_code

def main():
    if len(sys.argv) < 2:
        print("Usage: python bot_test_runner.py <bot_script_path>")
        sys.exit(1)

    bot_script_path = sys.argv[1]
    test_runner = StarCraftBotTestRunner(bot_script_path)
    result = test_runner.run_bot_test()
    sys.exit(result)

if __name__ == "__main__":
    main()

import sys
from typing import List, Set

class UnformedSum:
    @staticmethod
    def unformed_sum(arr: List[int]) -> int:
        if not arr:
            return 1

        my_set: Set[int] = {0}

        def process(index: int, current_sum: int) -> None:
            if index == len(arr):
                return

            temp_set = my_set.copy()
            for existing_sum in temp_set:
                new_sum = existing_sum + arr[index]
                my_set.add(new_sum)

            process(index + 1, current_sum)

        process(0, 0)

        target = 1
        while target in my_set:
            target += 1

        return target

    @staticmethod
    def unformed_sum_dp(arr: List[int]) -> int:
        if not arr:
            return 1

        arr.sort()
        max_sum = sum(arr)
        dp = [False] * (max_sum + 2)
        dp[0] = True

        for num in arr:
            for j in range(max_sum, num - 1, -1):
                if dp[j - num]:
                    dp[j] = True

        for i in range(1, max_sum + 2):
            if not dp[i]:
                return i

        return max_sum + 2

    @staticmethod
    def unformed_sum_contained_1(arr: List[int]) -> int:
        if not arr:
            return 1

        sorted_arr = sorted(arr)

        if sorted_arr[0] > 1:
            return 1

        result = 1
        for num in sorted_arr:
            if num > result:
                break
            result += num

        return result

def test_unformed_sum():
    test_cases = [
        [1, 2, 3, 10],
        [1, 1, 1, 1],
        [2, 3, 4, 5],
        [1, 3, 6, 10, 11],
        []
    ]

    methods = [
        UnformedSum.unformed_sum,
        UnformedSum.unformed_sum_dp,
        UnformedSum.unformed_sum_contained_1
    ]

    for method in methods:
        print(f"Testing method: {method.__name__}")
        for case in test_cases:
            try:
                result = method(case.copy())
                print(f"Input: {case}, Smallest Unformed Sum: {result}")
            except Exception as e:
                print(f"Error processing case {case}: {e}")
        print()

def main():
    test_unformed_sum()

if __name__ == "__main__":
    main()

import os
import time
import threading
import psutil
import netifaces

class Config:
    def __init__(self):
        self.ignored_interfaces = [
            'lo', 'docker', 'veth', 'virbr', 
            'vmnet', 'vbox', 'bridge'
        ]
        self.update_interval = 5
        self.max_historical_points = 60

class Plugin:
    def __init__(self):
        self.config = Config()
        self.nics = {}
        self.lock = threading.Lock()
        self.running = False
        self.thread = None
        self.last_update_time = 0

    def _is_ignored(self, interface):
        return any(ignore in interface.lower() for ignore in self.config.ignored_interfaces)

    def _net_io_counters(self):
        try:
            return psutil.net_io_counters(pernic=True)
        except Exception as e:
            print(f"Network IO counters error: {e}")
            return {}

    def _deltas(self, current, previous, duration):
        deltas = {}
        for interface, stats in current.items():
            if self._is_ignored(interface):
                continue

            if interface in previous:
                prev_stats = previous[interface]
                deltas[interface] = {
                    'bytes_sent_ps': (stats.bytes_sent - prev_stats.bytes_sent) / duration,
                    'bytes_recv_ps': (stats.bytes_recv - prev_stats.bytes_recv) / duration,
                    'packets_sent_ps': (stats.packets_sent - prev_stats.packets_sent) / duration,
                    'packets_recv_ps': (stats.packets_recv - prev_stats.packets_recv) / duration,
                    'errin_ps': (stats.errin - prev_stats.errin) / duration,
                    'errout_ps': (stats.errout - prev_stats.errout) / duration
                }

        return deltas

    def update(self):
        current_time = time.time()
        duration = current_time - self.last_update_time

        with self.lock:
            current_stats = self._net_io_counters()
            if self.last_update_time > 0:
                network_deltas = self._deltas(current_stats, self.nics.get('stats', {}), duration)
                for interface, metrics in network_deltas.items():
                    if interface not in self.nics:
                        self.nics[interface] = {'history': []}

                    self.nics[interface]['current'] = metrics
                    self.nics[interface]['history'].append(metrics)

                    if len(self.nics[interface]['history']) > self.config.max_historical_points:
                        self.nics[interface]['history'].pop(0)

            self.nics['stats'] = current_stats
            self.last_update_time = current_time

    def _monitoring_thread(self):
        while self.running:
            self.update()
            time.sleep(self.config.update_interval)

    def enable(self):
        if not self.running:
            self.running = True
            self.thread = threading.Thread(target=self._monitoring_thread)
            self.thread.daemon = True
            self.thread.start()

    def disable(self):
        if self.running:
            self.running = False
            if self.thread:
                self.thread.join()
                self.thread = None

    def get_network_info(self):
        with self.lock:
            interfaces = []
            for name, info in self.nics.items():
                if name != 'stats' and 'current' in info:
                    interfaces.append({
                        'name': name,
                        'metrics': info.get('current', {}),
                        'history': info.get('history', [])
                    })
            return interfaces

def main():
    network_plugin = Plugin()
    network_plugin.enable()

    try:
        while True:
            time.sleep(10)
            network_info = network_plugin.get_network_info()
            print(f"Network Interfaces: {len(network_info)}")
    except KeyboardInterrupt:
        network_plugin.disable()

if __name__ == "__main__":
    main()

import unittest
import uuid
import os
import sys
from typing import Dict, Any, List, Union

class DictionarySerializer:
    @staticmethod
    def serialize(obj):
        if hasattr(obj, 'to_dict'):
            return obj.to_dict()
        elif isinstance(obj, dict):
            return {k: DictionarySerializer.serialize(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [DictionarySerializer.serialize(item) for item in obj]
        return obj

    @staticmethod
    def deserialize(data, cls=None):
        if cls and hasattr(cls, 'from_dict'):
            return cls.from_dict(data)
        elif isinstance(data, dict):
            return {k: DictionarySerializer.deserialize(v) for k, v in data.items()}
        elif isinstance(data, list):
            return [DictionarySerializer.deserialize(item) for item in data]
        return data

class WorkflowStep:
    def __init__(self, name, data=None):
        self.name = name
        self.data = data or {}
        self.id = str(uuid.uuid4())

    def to_dict(self):
        return {
            'name': self.name,
            'data': self.data,
            'id': self.id
        }

    @classmethod
    def from_dict(cls, data):
        step = cls(data['name'], data.get('data', {}))
        step.id = data.get('id', str(uuid.uuid4()))
        return step

class Workflow:
    def __init__(self, name):
        self.name = name
        self.steps = []
        self.id = str(uuid.uuid4())

    def add_step(self, step):
        self.steps.append(step)

    def to_dict(self):
        return {
            'name': self.name,
            'steps': [step.to_dict() for step in self.steps],
            'id': self.id
        }

    @classmethod
    def from_dict(cls, data):
        workflow = cls(data['name'])
        workflow.id = data.get('id', str(uuid.uuid4()))
        workflow.steps = [WorkflowStep.from_dict(step) for step in data.get('steps', [])]
        return workflow

class DictionarySerializerTest(unittest.TestCase):
    def setUp(self):
        self.workflow = Workflow("Test Workflow")
        step1 = WorkflowStep("Initial Step", {"key1": "value1"})
        step2 = WorkflowStep("Next Step", {"key2": "value2"})
        self.workflow.add_step(step1)
        self.workflow.add_step(step2)

    def _compare_results(self, original, deserialized, ignore_keys=None):
        ignore_keys = ignore_keys or []

        def recursive_compare(orig, deser):
            if isinstance(orig, dict) and isinstance(deser, dict):
                for key, value in orig.items():
                    if key in ignore_keys:
                        continue
                    self.assertIn(key, deser, f"Key {key} not found in deserialized data")
                    recursive_compare(value, deser[key])
            elif isinstance(orig, list) and isinstance(deser, list):
                self.assertEqual(len(orig), len(deser), "List lengths do not match")
                for orig_item, deser_item in zip(orig, deser):
                    recursive_compare(orig_item, deser_item)
            else:
                self.assertEqual(orig, deser, f"Values do not match: {orig} vs {deser}")

        recursive_compare(original, deserialized)

    def test_workflow_serialization(self):
        # Serialize workflow
        serialized_workflow = DictionarySerializer.serialize(self.workflow)

        # Deserialize workflow
        deserialized_workflow = DictionarySerializer.deserialize(
            serialized_workflow, Workflow
        )

        # Compare results, ignoring dynamic IDs
        ignore_keys = ['id']
        self._compare_results(
            self.workflow.to_dict(), 
            deserialized_workflow.to_dict(), 
            ignore_keys
        )

def suite():
    test_suite = unittest.TestSuite()
    test_suite.addTest(unittest.makeSuite(DictionarySerializerTest))
    return test_suite

if __name__ == '__main__':
    runner = unittest.TextTestRunner()
    test_suite = suite()
    runner.run(test_suite)

class Sprite:
    def __init__(self, x, y, w, h):
        self.x = x
        self.y = y
        self.width = w
        self.height = h
        self.dx = 0
        self.dy = 0
        self.pics = []
        self.currentPic = 0
        self.state = "idle"
        self.dir = 1

    def loadPics(self, filePrefix):
        for i in range(4):
            try:
                img = loadImage(f"{filePrefix}_{i}.png")
                self.pics.append(img)
            except Exception:
                break

    def display(self):
        if self.pics:
            img = self.pics[self.currentPic]
            if self.dir < 0:
                pushMatrix()
                scale(-1, 1)
                image(img, -self.x - self.width, self.y, self.width, self.height)
                popMatrix()
            else:
                image(img, self.x, self.y, self.width, self.height)

    def animate(self):
        if frameCount % 10 == 0:
            self.currentPic = (self.currentPic + 1) % len(self.pics)

class Actor(Sprite):
    def __init__(self, x, y):
        super().__init__(x, y, 50, 80)
        self.speed = 3
        self.jumpStrength = 8
        self.isGrounded = False

    def move(self):
        if keyPressed:
            if keyCode == LEFT:
                self.dx = -self.speed
                self.dir = -1
                self.state = "walking"
            elif keyCode == RIGHT:
                self.dx = self.speed
                self.dir = 1
                self.state = "walking"
            elif keyCode == UP and self.isGrounded:
                self.dy = -self.jumpStrength
                self.isGrounded = False

        self.x += self.dx
        self.y += self.dy
        self.dy += 0.5  # Gravity

        self.checkWall()
        self.animate()

    def checkWall(self):
        if self.x < 0:
            self.x = 0
        elif self.x > 640 - self.width:
            self.x = 640 - self.width

        if self.y > height - self.height:
            self.y = height - self.height
            self.dy = 0
            self.isGrounded = True

class Block(Sprite):
    def __init__(self, x, y, w, h):
        super().__init__(x, y, w, h)
        self.color = color(100, 150, 200)

    def display(self):
        fill(self.color)
        rect(self.x, self.y, self.width, self.height)

def checkCollision(actor, block):
    return (actor.x < block.x + block.width and
            actor.x + actor.width > block.x and
            actor.y < block.y + block.height and
            actor.y + actor.height > block.y)

def setup():
    size(640, 480)
    player = Actor(100, 300)
    player.loadPics("player")
    obstacles = [
        Block(200, 400, 100, 50),
        Block(400, 350, 150, 30)
    ]

def draw():
    background(220)
    player.move()
    player.display()

    for obstacle in obstacles:
        obstacle.display()
        if checkCollision(player, obstacle):
            player.isGrounded = True
            player.y = obstacle.y - player.height

def keyPressed():
    if key == ' ':
        player.dx = 0
        player.state = "idle"

def mousePressed():
    println("Game interaction triggered")

import numpy as np
import logging
from typing import Dict, List, Callable
from dataclasses import dataclass, field

class OptimizationError(Exception):
    """Custom exception for optimization failures."""
    pass

@dataclass
class DeviceProperties:
    name: str
    min_value: float
    max_value: float
    default_value: float
    step_size: float = 0.01

class MachineInterface:
    def __init__(self, devices: Dict[str, DeviceProperties]):
        self._devices = devices
        self._current_state = {}
        self.logger = logging.getLogger(self.__class__.__name__)

    def get_value(self, device_name: str) -> float:
        try:
            return self._current_state.get(device_name, 0.0)
        except KeyError:
            raise OptimizationError(f"Device {device_name} not found")

    def set_value(self, device_name: str, value: float) -> None:
        device = self._devices.get(device_name)
        if not device:
            raise OptimizationError(f"Invalid device: {device_name}")

        clamped_value = max(device.min_value, min(value, device.max_value))
        self._current_state[device_name] = clamped_value

@dataclass
class OptimizationAction:
    device: str
    objective_func: Callable[[float], float]
    search_strategy: str = "simplex"
    max_iterations: int = 50

class Optimizer:
    def __init__(self, machine_interface: MachineInterface):
        self.interface = machine_interface
        self.actions: List[OptimizationAction] = []
        self.logger = logging.getLogger(self.__class__.__name__)

    def add_action(self, action: OptimizationAction) -> None:
        self.actions.append(action)

    def optimize(self) -> Dict[str, float]:
        results = {}
        for action in self.actions:
            try:
                optimized_value = self._optimize_device(action)
                results[action.device] = optimized_value
            except Exception as e:
                self.logger.error(f"Optimization failed for {action.device}: {e}")

        return results

    def _optimize_device(self, action: OptimizationAction) -> float:
        current_value = self.interface.get_value(action.device)

        if action.search_strategy == "simplex":
            return self._simplex_optimize(action, current_value)
        elif action.search_strategy == "gradient":
            return self._gradient_optimize(action, current_value)
        else:
            raise OptimizationError(f"Unknown strategy: {action.search_strategy}")

    def _simplex_optimize(self, action: OptimizationAction, start_value: float) -> float:
        best_value = start_value
        best_score = action.objective_func(best_value)

        for _ in range(action.max_iterations):
            test_values = [
                best_value * (1 + 0.1),
                best_value * (1 - 0.1)
            ]

            for test_val in test_values:
                score = action.objective_func(test_val)
                if score > best_score:
                    best_value = test_val
                    best_score = score

        self.interface.set_value(action.device, best_value)
        return best_value

    def _gradient_optimize(self, action: OptimizationAction, start_value: float) -> float:
        current_value = start_value
        learning_rate = 0.01

        for _ in range(action.max_iterations):
            gradient = self._estimate_gradient(action.objective_func, current_value)
            current_value += learning_rate * gradient

        self.interface.set_value(action.device, current_value)
        return current_value

    def _estimate_gradient(self, func: Callable[[float], float], x: float, epsilon: float = 1e-8) -> float:
        return (func(x + epsilon) - func(x)) / epsilon

def create_sase_objective(target_value: float) -> Callable[[float], float]:
    def objective(x: float) -> float:
        # Mock objective function for SASE maximization
        return np.exp(-(x - target_value)**2)
    return objective

def main():
    logging.basicConfig(level=logging.INFO)

    devices = {
        "quad1": DeviceProperties("quad1", -10, 10, 0),
        "corrector_x": DeviceProperties("corrector_x", -5, 5, 0),
        "corrector_y": DeviceProperties("corrector_y", -5, 5, 0)
    }

    machine_interface = MachineInterface(devices)
    optimizer = Optimizer(machine_interface)

    sase_objective = create_sase_objective(target_value=2.5)

    optimizer.add_action(OptimizationAction(
        device="quad1",
        objective_func=sase_objective,
        search_strategy="simplex"
    ))

    results = optimizer.optimize()
    print("Optimization Results:", results)

if __name__ == "__main__":
    main()

import os
from fabric.api import env, local, sudo, run, cd, prefix, task
from fabric.contrib.files import exists

# Environment Configuration
env.user = 'ubuntu'
env.repo_url = 'https://github.com/username/project.git'
env.root = '/var/www/myproject'
env.virtualenv = '/var/www/myproject/venv'
env.project = 'myproject'
env.servicename = 'myproject_service'

def get_env_variable(var_name):
    """Retrieve environment variables safely."""
    try:
        return os.environ[var_name]
    except KeyError:
        error_msg = f"Set the {var_name} environment variable"
        raise Exception(error_msg)

@task
def setup():
    """Complete server setup and initialization."""
    sudo('apt-get update')
    sudo('apt-get install -y python3-pip python3-venv nginx git')

    if not exists(env.root):
        sudo(f'mkdir -p {env.root}')
        sudo(f'chown -R {env.user}:{env.user} {env.root}')

    with cd(env.root):
        run('git clone {} .'.format(env.repo_url))

        # Create virtual environment
        run(f'python3 -m venv {env.virtualenv}')

        with prefix(f'source {env.virtualenv}/bin/activate'):
            run('pip install --upgrade pip')
            run('pip install -r requirements.txt')
            run('pip install gunicorn')

    configure_nginx()
    configure_systemd()
    database_setup()

def configure_nginx():
    """Configure Nginx for the Django project."""
    nginx_config = f'''
    server {{
        listen 80;
        server_name {get_env_variable('DOMAIN_NAME')};

        location /static/ {{
            alias {env.root}/static/;
        }}

        location / {{
            proxy_pass http://127.0.0.1:8000;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
        }}
    }}
    '''

    sudo(f'echo "{nginx_config}" > /etc/nginx/sites-available/{env.project}')
    sudo(f'ln -sf /etc/nginx/sites-available/{env.project} /etc/nginx/sites-enabled/')
    sudo('nginx -t')
    sudo('systemctl restart nginx')

def configure_systemd():
    """Create systemd service for gunicorn."""
    service_config = f'''
    [Unit]
    Description={env.project} Gunicorn Service
    After=network.target

    [Service]
    User={env.user}
    Group={env.user}
    WorkingDirectory={env.root}
    ExecStart={env.virtualenv}/bin/gunicorn \
        --workers 3 \
        --bind 127.0.0.1:8000 \
        {env.project}.wsgi:application

    [Install]
    WantedBy=multi-user.target
    '''

    sudo(f'echo "{service_config}" > /etc/systemd/system/{env.servicename}.service')
    sudo('systemctl daemon-reload')
    sudo(f'systemctl enable {env.servicename}')
    sudo(f'systemctl start {env.servicename}')

def database_setup():
    """Perform database migrations."""
    with cd(env.root), prefix(f'source {env.virtualenv}/bin/activate'):
        run('python manage.py migrate')
        run('python manage.py collectstatic --noinput')

@task
def deploy():
    """Deploy latest code to server."""
    with cd(env.root):
        run('git pull origin main')

        with prefix(f'source {env.virtualenv}/bin/activate'):
            run('pip install -r requirements.txt')
            run('python manage.py migrate')
            run('python manage.py collectstatic --noinput')

    sudo(f'systemctl restart {env.servicename}')
    sudo('systemctl restart nginx')

@task
def createsuperuser():
    """Create a Django superuser."""
    with cd(env.root), prefix(f'source {env.virtualenv}/bin/activate'):
        run('python manage.py createsuperuser')

import numbers
import collections.abc
from typing import Any, Dict, Union, Optional

def expanded_indexer(key, ndim):
    """
    Expand and normalize indexing keys across multiple dimensions.

    Args:
        key: Indexing key or tuple of keys
        ndim: Total number of dimensions in the array

    Returns:
        Normalized indexing tuple
    """
    if key is None:
        return (slice(None),) * ndim

    if isinstance(key, slice):
        return (key,) + (slice(None),) * (ndim - 1)

    if not isinstance(key, tuple):
        key = (key,)

    if len(key) > ndim:
        raise IndexError(f"Too many indices for array: got {len(key)}, array has {ndim} dimensions")

    expanded_key = []
    for index in key:
        if index is Ellipsis:
            expanded_key.extend([slice(None)] * (ndim - len(key) + 1))
        elif isinstance(index, slice) or isinstance(index, numbers.Integral):
            expanded_key.append(index)
        else:
            raise TypeError(f"Invalid index type: {type(index)}")

    # Pad with full slices if needed
    expanded_key.extend([slice(None)] * (ndim - len(expanded_key)))

    return tuple(expanded_key)

def is_dict_like(obj):
    """
    Check if an object is dictionary-like.

    Args:
        obj: Object to check

    Returns:
        Boolean indicating dictionary-like behavior
    """
    return (
        hasattr(obj, 'keys') and 
        hasattr(obj, '__getitem__') and 
        isinstance(obj, collections.abc.Mapping)
    )

def either_dict_or_kwargs(
    input_dict: Optional[Dict[str, Any]] = None, 
    **kwargs: Any
) -> Dict[str, Any]:
    """
    Resolve arguments from either a dictionary or keyword arguments.

    Args:
        input_dict: Optional input dictionary
        **kwargs: Keyword arguments

    Returns:
        Merged dictionary of arguments

    Raises:
        TypeError: If both dictionary and keyword arguments are provided
    """
    if input_dict is not None and kwargs:
        raise TypeError("Cannot specify both a dictionary and keyword arguments")

    if input_dict is not None:
        if not is_dict_like(input_dict):
            raise TypeError("Input must be a dictionary-like object")
        return dict(input_dict)

    return dict(kwargs)

def sanitize_slice(
    slice_obj: Union[slice, int, None], 
    max_length: Optional[int] = None
) -> slice:
    """
    Normalize and validate slice objects.

    Args:
        slice_obj: Input slice or index
        max_length: Optional maximum length for slice validation

    Returns:
        Normalized slice object
    """
    if slice_obj is None:
        return slice(None)

    if isinstance(slice_obj, numbers.Integral):
        slice_obj = slice(slice_obj, slice_obj + 1)

    start = slice_obj.start or 0
    stop = slice_obj.stop
    step = slice_obj.step or 1

    if max_length is not None:
        start = max(0, min(start, max_length))

        if stop is not None:
            stop = max(0, min(stop, max_length))

    return slice(start, stop, step)

import hashlib
import sys

__b58chars = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz'
__b58base = len(__b58chars)

def b58encode(v):
    """Base58 encode a string of bytes"""
    long_value = int.from_bytes(v, byteorder='big')

    if sys.version_info[0] < 3:
        long_value = long(long_value)

    result = ''
    while long_value >= __b58base:
        div, mod = divmod(long_value, __b58base)
        result = __b58chars[mod] + result
        long_value = div

    result = __b58chars[long_value] + result

    # Encode leading zeros as base58 zeros
    npad = 0
    for c in v:
        if c == 0:
            npad += 1
        else:
            break

    return __b58chars[0] * npad + result

def b58decode(v):
    """Decode a base58-encoded string"""
    if not isinstance(v, str):
        raise TypeError('a string argument is required')

    long_value = 0
    for char in v:
        long_value = long_value * __b58base + __b58chars.index(char)

    result = long_value.to_bytes((long_value.bit_length() + 7) // 8, byteorder='big')

    # Add leading zeros
    pad = 0
    for c in v:
        if c == __b58chars[0]:
            pad += 1
        else:
            break

    return b'\x00' * pad + result

def checksum(v):
    """Generate a 4-byte checksum"""
    hash1 = hashlib.sha256(v).digest()
    hash2 = hashlib.sha256(hash1).digest()
    return hash2[:4]

def b58encode_chk(v):
    """Encode with attached 4-byte checksum"""
    chk = checksum(v)
    return b58encode(v + chk)

def b58decode_chk(v):
    """Decode and verify 4-byte checksum"""
    decoded = b58decode(v)
    result, chk = decoded[:-4], decoded[-4:]

    if checksum(result) != chk:
        raise ValueError('Invalid checksum')

    return result

def get_bcaddress_version(v):
    """Extract address version from a Base58Check encoded address"""
    try:
        decoded = b58decode(v)
        result = decoded[0] if len(decoded) > 1 else None
        return result
    except Exception:
        return None

def is_valid_bitcoin_address(address):
    """Validate Bitcoin address"""
    try:
        decoded = b58decode_chk(address)
        return len(decoded) == 21
    except Exception:
        return False

def main():
    # Test encoding and decoding
    test_data = b'Hello, Blockchain!'

    # Encode test
    encoded = b58encode(test_data)
    print(f"Original: {test_data}")
    print(f"Encoded: {encoded}")

    # Decode test
    decoded = b58decode(encoded)
    print(f"Decoded: {decoded}")

    # Checksum test
    chk_encoded = b58encode_chk(test_data)
    print(f"Checksum Encoded: {chk_encoded}")

    try:
        chk_decoded = b58decode_chk(chk_encoded)
        print(f"Checksum Decoded: {chk_decoded}")
    except ValueError as e:
        print(f"Checksum error: {e}")

if __name__ == "__main__":
    main()

import os
import json
import hashlib
import subprocess

_TREE_PATH = "/opt/graph_cache"
_RENDER_SCRIPT = "/bin/to_graph.sh"

class GraphRenderer:
    def __init__(self, base_path=_TREE_PATH):
        self.base_path = base_path
        self.bucket_table = {}
        self.load_bucket_table()

    def load_bucket_table(self):
        table_path = os.path.join(self.base_path, "bucket_table.json")
        if os.path.exists(table_path):
            with open(table_path, 'r') as f:
                self.bucket_table = json.load(f)

    def save_bucket_table(self):
        table_path = os.path.join(self.base_path, "bucket_table.json")
        with open(table_path, 'w') as f:
            json.dump(self.bucket_table, f)

    def hash_func(self, query, params):
        hash_input = json.dumps(query) + json.dumps(params, sort_keys=True)
        return hashlib.md5(hash_input.encode()).hexdigest()

    def parse_tex_query(self, query):
        # Basic parsing logic for LaTeX-like graph queries
        return query.replace('\\', '').strip()

    def handle_tex_render_error(self, error):
        print(f"Rendering Error: {error}")
        return None

    def render_graph(self, query, params=None):
        if params is None:
            params = {
                'x_range': [-10, 10],
                'y_range': [-10, 10],
                'title': 'Graph',
                'labels': True
            }

        query_hash = self.hash_func(query, params)
        bucket = query_hash[:2]

        # Check if graph is already cached
        if bucket in self.bucket_table and query_hash in self.bucket_table[bucket]:
            return self.bucket_table[bucket][query_hash]

        # Prepare rendering directory
        bucket_path = os.path.join(self.base_path, bucket)
        os.makedirs(bucket_path, exist_ok=True)

        # Render graph using external script
        try:
            rendered_file = os.path.join(bucket_path, f"{query_hash}.svg")
            parsed_query = self.parse_tex_query(query)

            subprocess.run([
                _RENDER_SCRIPT, 
                parsed_query, 
                rendered_file, 
                json.dumps(params)
            ], check=True)

            # Update bucket table
            if bucket not in self.bucket_table:
                self.bucket_table[bucket] = {}

            self.bucket_table[bucket][query_hash] = rendered_file
            self.save_bucket_table()

            return rendered_file

        except subprocess.CalledProcessError as e:
            return self.handle_tex_render_error(e)

    def clean_cache(self, max_entries=1000):
        all_entries = []
        for bucket, entries in self.bucket_table.items():
            all_entries.extend(entries.items())

        # Sort by creation time or implement more sophisticated eviction policy
        all_entries.sort(key=lambda x: os.path.getctime(x[1]))

        if len(all_entries) > max_entries:
            for hash_key, file_path in all_entries[:len(all_entries) - max_entries]:
                bucket = hash_key[:2]
                del self.bucket_table[bucket][hash_key]
                os.remove(file_path)

            self.save_bucket_table()

def main():
    renderer = GraphRenderer()
    graph_file = renderer.render_graph("sin(x)", {"x_range": [-5, 5]})
    print(f"Rendered graph: {graph_file}")

if __name__ == "__main__":
    main()

from django.shortcuts import get_object_or_404, render
from django.contrib.auth.decorators import login_required
from django.http import HttpResponseRedirect
from wagtail.admin.views.generic import PermissionCheckedMixin
from wagtail.admin.views.pages import ModelFormView
from wagtail.core.models import Page, PageViewRestriction
from wagtail.admin.forms import PageViewRestrictionForm
from django.utils.translation import gettext_lazy as _
from django.core.exceptions import PermissionDenied

class PagePrivacyView(PermissionCheckedMixin, ModelFormView):
    permission_required = 'change_page'
    model = PageViewRestriction
    form_class = PageViewRestrictionForm
    page_title = _("Set page privacy")
    header_icon = 'lock'

    def get_page(self):
        return get_object_or_404(Page, pk=self.kwargs['page_pk'])

    def get_form_kwargs(self):
        kwargs = super().get_form_kwargs()
        kwargs['page'] = self.get_page()
        return kwargs

    def get_existing_restrictions(self):
        return PageViewRestriction.objects.filter(page=self.get_page())

    def check_page_permission(self):
        page = self.get_page()
        page_perms = page.permissions_for_user(self.request.user)

        if not page_perms.can_change_privacy:
            raise PermissionDenied(_("You do not have permission to modify this page's privacy."))

        # Check for ancestor restrictions
        if page.get_view_restrictions_enum() != Page.VIEW_RESTRICTIONS_NONE:
            raise PermissionDenied(_("Page has existing ancestor-level restrictions."))

    def form_valid(self, form):
        self.check_page_permission()

        # Handle restriction type
        if form.cleaned_data['restriction_type'] == 'none':
            self.get_existing_restrictions().delete()
        else:
            restriction = form.save(commit=False)
            restriction.page = self.get_page()
            restriction.save()

        return HttpResponseRedirect(self.get_success_url())

    def get_context_data(self, **kwargs):
        context = super().get_context_data(**kwargs)
        context['page'] = self.get_page()
        context['restrictions'] = self.get_existing_restrictions()
        return context

    def get_success_url(self):
        return self.get_page().get_edit_url()

def set_privacy(request, page_pk):
    """
    Modal workflow for setting page privacy restrictions.
    """
    try:
        page = get_object_or_404(Page, pk=page_pk)
        page_perms = page.permissions_for_user(request.user)

        if not page_perms.can_change_privacy:
            raise PermissionDenied(_("Insufficient permissions"))

        existing_restrictions = PageViewRestriction.objects.filter(page=page)

        if request.method == 'POST':
            form = PageViewRestrictionForm(request.POST, page=page)
            if form.is_valid():
                # Process form submission
                if form.cleaned_data['restriction_type'] == 'none':
                    existing_restrictions.delete()
                else:
                    restriction = form.save(commit=False)
                    restriction.page = page
                    restriction.save()
                return HttpResponseRedirect(page.get_edit_url())
        else:
            form = PageViewRestrictionForm(page=page)

        return render(
            request, 
            'wagtailadmin/pages/privacy_modal.html', 
            {
                'page': page,
                'form': form,
                'restrictions': existing_restrictions
            }
        )

    except Exception as e:
        # Log error or handle specific exceptions
        raise PermissionDenied(_("Error processing page privacy"))

import xml.etree.ElementTree as ET
import os
import traceback

class XMLControl:
    def __init__(self, path=None):
        self.path = path
        self.tree = None
        self.encoding = 'utf-8'

        if path and os.path.exists(path):
            self.load_xml(path)
        else:
            self.tree = ET.ElementTree(ET.Element('game_config'))

    def set_path(self, path):
        """Set the configuration file path."""
        self.path = path
        return self

    def get_tree(self):
        """Retrieve the current XML element tree."""
        return self.tree

    def set_tree(self, tree):
        """Set a new XML element tree."""
        self.tree = tree
        return self

    def find_or_create_node(self, parent, node_name, attributes=None):
        """Find an existing node or create a new one if not found."""
        node = parent.find(node_name)

        if node is None:
            node = ET.SubElement(parent, node_name)

        if attributes:
            for key, value in attributes.items():
                node.set(key, str(value))

        return node

    def load_xml(self, filepath=None):
        """Load XML configuration from file."""
        try:
            filepath = filepath or self.path

            if not filepath or not os.path.exists(filepath):
                raise FileNotFoundError(f"File not found: {filepath}")

            self.tree = ET.parse(filepath)
            self.path = filepath
            return self

        except ET.ParseError as e:
            print(f"XML Parsing Error: {e}")
            traceback.print_exc()
            return None

        except Exception as e:
            print(f"Unexpected error loading XML: {e}")
            traceback.print_exc()
            return None

    def save_xml(self, filepath=None, override=True):
        """Save XML configuration to file."""
        try:
            filepath = filepath or self.path

            if not filepath:
                raise ValueError("No file path specified")

            if os.path.exists(filepath) and not override:
                print(f"File {filepath} already exists. Set override=True to replace.")
                return False

            self.indent_tree(self.tree.getroot())
            self.tree.write(filepath, encoding=self.encoding, xml_declaration=True)

            print(f"XML saved successfully to {filepath}")
            return True

        except Exception as e:
            print(f"Error saving XML: {e}")
            traceback.print_exc()
            return False

    def indent_tree(self, elem, level=0, indent="    "):
        """Add indentation to XML tree for better readability."""
        i = "\n" + level * indent
        if len(elem):
            if not elem.text or not elem.text.strip():
                elem.text = i + indent
            if not elem.tail or not elem.tail.strip():
                elem.tail = i

            for subelem in elem:
                self.indent_tree(subelem, level + 1, indent)

            if not elem.tail or not elem.tail.strip():
                elem.tail = i
        else:
            if level and (not elem.tail or not elem.tail.strip()):
                elem.tail = i

    def connect_game(self, game_name, attributes=None):
        """Create or update game configuration node."""
        root = self.tree.getroot()
        game_node = self.find_or_create_node(root, 'game', 
                                             {'name': game_name})

        if attributes:
            for key, value in attributes.items():
                game_node.set(key, str(value))

        return game_node

    def set_game_attribute(self, game_name, key, value):
        """Set a specific attribute for a game configuration."""
        game_node = self.tree.getroot().find(f"game[@name='{game_name}']")

        if game_node is not None:
            game_node.set(key, str(value))
        else:
            print(f"Game '{game_name}' not found")

    def get_game_attribute(self, game_name, key, default=None):
        """Retrieve a game configuration attribute."""
        game_node = self.tree.getroot().find(f"game[@name='{game_name}']")

        if game_node is not None:
            return game_node.get(key, default)

        return default

    def delete_game(self, game_name):
        """Remove a game configuration node."""
        root = self.tree.getroot()
        game_node = root.find(f"game[@name='{game_name}']")

        if game_node is not None:
            root.remove(game_node)
            return True

        return False

import PyQt4.QtGui as QtGui
import PyQt4.QtCore as QtCore
import e3
import gui
import extension

class StatusButton(QtGui.QPushButton):
    """
    Custom status selection button for instant messaging application
    """
    def __init__(self, session=None):
        QtGui.QPushButton.__init__(self)

        self.session = session
        self.cache_imgs = {}
        self.invertStatus = {
            'online': 'offline',
            'offline': 'online',
            'away': 'busy',
            'busy': 'away'
        }

        self.status_menu = QtGui.QMenu()
        self.setMenu(self.status_menu)

        self._setup_ui()
        self._create_status_actions()

        self.clicked.connect(self.showMenu)

    def _setup_ui(self):
        """Configure initial button appearance"""
        self.setMinimumWidth(80)
        self.setFlat(True)
        self.setToolTip('Change Status')

    def _create_status_actions(self):
        """Generate status menu actions"""
        status_options = [
            ('online', 'Available'),
            ('away', 'Away'),
            ('busy', 'Busy'),
            ('offline', 'Invisible')
        ]

        for status_key, status_text in status_options:
            action = self.status_menu.addAction(status_text)
            action.triggered.connect(
                lambda checked, sk=status_key: self.statusactionchange(sk)
            )

    def statusactionchange(self, status):
        """Handle status change action"""
        if self.session:
            self.session.set_status(status)
        self.set_status(status)

    def set_status(self, status):
        """Update button's visual representation"""
        if status not in self.cache_imgs:
            icon_path = self._get_status_icon_path(status)
            pixmap = QtGui.QPixmap(icon_path)
            icon = QtGui.QIcon(pixmap)
            self.cache_imgs[status] = icon

        self.setIcon(self.cache_imgs[status])
        self.setText(self._get_status_label(status))

    def _get_status_icon_path(self, status):
        """Retrieve status icon path"""
        icon_paths = {
            'online': 'icons/online.png',
            'away': 'icons/away.png',
            'busy': 'icons/busy.png',
            'offline': 'icons/offline.png'
        }
        return icon_paths.get(status, 'icons/default.png')

    def _get_status_label(self, status):
        """Generate status label"""
        status_labels = {
            'online': 'Available',
            'away': 'Away',
            'busy': 'Busy',
            'offline': 'Invisible'
        }
        return status_labels.get(status, 'Unknown')

    def showMenu(self):
        """Display status menu at button location"""
        menu_pos = self.mapToGlobal(
            QtCore.QPoint(0, self.height())
        )
        self.status_menu.popup(menu_pos)

    def update_session_status(self, status):
        """Update session and button status"""
        if self.session:
            self.session.set_status(status)
        self.set_status(status)

    def toggle_status(self):
        """Toggle between status states"""
        current_status = self.status
        next_status = self.invertStatus.get(current_status, 'online')
        self.update_session_status(next_status)

#!/usr/bin/env python3
import random
import logging
import argparse
from typing import List, Optional
from scapy.all import (
    Ether, IP, UDP, BOOTP, DHCP, sendp, sniff, conf
)

class DHCPUtility:
    def __init__(self, interface: str):
        self.interface = interface
        logging.basicConfig(
            level=logging.INFO,
            format='[%(asctime)s] %(levelname)s: %(message)s'
        )
        self.logger = logging.getLogger(__name__)

    def generate_random_mac(self) -> str:
        """Generate a random MAC address."""
        return ":".join([
            f"{random.randint(0x00, 0xff):02x}" for _ in range(6)
        ])

    def create_dhcp_discover_packet(self) -> Ether:
        """Create a DHCP discovery packet with random MAC."""
        mac_addr = self.generate_random_mac()
        dhcp_discover = (
            Ether(dst="ff:ff:ff:ff:ff:ff", src=mac_addr) /
            IP(src="0.0.0.0", dst="255.255.255.255") /
            UDP(sport=68, dport=67) /
            BOOTP(
                op=1, chaddr=mac_addr.replace(':', '').decode('hex'),
                xid=random.randint(1, 900000000)
            ) /
            DHCP(options=[
                ('message-type', 'discover'),
                'end'
            ])
        )
        return dhcp_discover

    def dhcp_flood(self, count: int = 100):
        """Flood network with DHCP discovery packets."""
        self.logger.info(f"Starting DHCP flood on {self.interface}")
        try:
            packets = [self.create_dhcp_discover_packet() for _ in range(count)]
            sendp(packets, iface=self.interface, verbose=False)
            self.logger.info(f"Sent {count} DHCP discovery packets")
        except Exception as e:
            self.logger.error(f"DHCP flood error: {e}")

    def parse_dhcp_response(self, packet):
        """Parse and display DHCP response details."""
        if DHCP in packet:
            options = dict(packet[DHCP].options)
            print("\n--- DHCP Response Details ---")
            print(f"MAC Address: {packet[Ether].src}")
            print(f"Server IP: {packet[IP].src}")
            print(f"Message Type: {options.get('message-type', 'Unknown')}")
            print(f"Offered IP: {packet[BOOTP].yiaddr}")
            print(f"DNS Servers: {options.get('name_server', 'N/A')}")
            print(f"Router: {options.get('router', 'N/A')}")
            print("----------------------------")

    def dhcp_sniff(self, duration: int = 30):
        """Capture and display DHCP response packets."""
        self.logger.info(f"Sniffing DHCP responses on {self.interface}")
        try:
            packets = sniff(
                iface=self.interface,
                filter="udp and (port 67 or port 68)",
                timeout=duration
            )
            for packet in packets:
                self.parse_dhcp_response(packet)
        except Exception as e:
            self.logger.error(f"DHCP sniff error: {e}")

def parse_args() -> argparse.Namespace:
    """Parse command-line arguments."""
    parser = argparse.ArgumentParser(description="DHCP Network Utility")
    parser.add_argument(
        "-i", "--interface", 
        required=True, 
        help="Network interface to use"
    )
    parser.add_argument(
        "-m", "--mode", 
        choices=['flood', 'sniff'], 
        default='sniff',
        help="Operation mode"
    )
    parser.add_argument(
        "-c", "--count", 
        type=int, 
        default=100, 
        help="Packet count for flooding"
    )
    parser.add_argument(
        "-d", "--duration", 
        type=int, 
        default=30, 
        help="Sniffing duration"
    )
    return parser.parse_args()

def main():
    """Main execution entry point."""
    try:
        args = parse_args()
        conf.verb = 0  # Suppress Scapy verbose output

        dhcp_util = DHCPUtility(args.interface)

        if args.mode == 'flood':
            dhcp_util.dhcp_flood(args.count)
        else:
            dhcp_util.dhcp_sniff(args.duration)

    except PermissionError:
        print("Error: Root/administrative privileges required")
    except Exception as e:
        print(f"Unexpected error: {e}")

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
# -*- coding: utf-8 -*-

import sys
import os
import configparser
import getopt
from weibo import Client

class WeiboCLI:
    def __init__(self):
        self.config_path = os.path.expanduser('~/.weibo_config')
        self.config = configparser.ConfigParser()
        self.client = None

    def load_config(self):
        if not os.path.exists(self.config_path):
            print("No configuration found. Please authenticate first.")
            return False

        self.config.read(self.config_path)
        return True

    def save_config(self, access_token, expires_in, uid):
        if not self.config.has_section('weibo'):
            self.config.add_section('weibo')

        self.config.set('weibo', 'access_token', access_token)
        self.config.set('weibo', 'expires_in', str(expires_in))
        self.config.set('weibo', 'uid', uid)

        with open(self.config_path, 'w') as configfile:
            self.config.write(configfile)

    def authenticate(self, api_key, api_secret, redirect_url):
        try:
            client = Client(
                api_key=api_key,
                api_secret=api_secret,
                redirect_uri=redirect_url
            )
            authorization_url = client.authorize_url
            print(f"Please visit: {authorization_url}")
            code = input("Enter authorization code: ")

            r = client.request_access_token(code)
            self.save_config(
                r.access_token, 
                r.expires_in, 
                r.uid
            )
            print("Authentication successful!")
        except Exception as e:
            print(f"Authentication error: {e}")

    def init_client(self):
        if not self.load_config():
            return False

        try:
            self.client = Client(
                api_key=self.config.get('weibo', 'api_key'),
                api_secret=self.config.get('weibo', 'api_secret'),
                redirect_uri=self.config.get('weibo', 'redirect_url'),
                access_token=self.config.get('weibo', 'access_token')
            )
            return True
        except Exception as e:
            print(f"Client initialization error: {e}")
            return False

    def get_timeline(self):
        if not self.init_client():
            return

        try:
            timeline = self.client.get('statuses/friends_timeline')
            for status in timeline['statuses'][:20]:
                print(f"@{status['user']['screen_name']}: {status['text']}")
        except Exception as e:
            print(f"Error retrieving timeline: {e}")

    def post_status(self, status_text):
        if not self.init_client():
            return

        try:
            self.client.post('statuses/update', status=status_text)
            print("Status posted successfully!")
        except Exception as e:
            print(f"Error posting status: {e}")

    def usage(self):
        print("""
Weibo CLI Utility
Usage:
  -a, --auth     Authenticate with Weibo
  -t, --timeline Retrieve friend timeline
  -p, --post     Post a new status
  -h, --help     Show this help message
        """)

def main():
    weibo_cli = WeiboCliWeiboO()

    try:
        opts, args = getopt.getopt(
            sys.argv[1:], 
            "hatp:", 
            ["help", "auth", "timeline", "post="]
        )
    except getopt.GetoptError as err:
        print(str(err))
        weibo_cli.usage()
        sys.exit(2)

    for opt, arg in opts:
        if opt in ('-h', '--help'):
            weibo_cli.usage()
        elif opt in ('-a', '--auth'):
            api_key = input("Enter API Key: ")
            api_secret = input("Enter API Secret: ")
            redirect_url = input("Enter Redirect URL: ")
            weibo_cli.authenticate(api_key, api_secret, redirect_url)
        elif opt in ('-t', '--timeline'):
            weibo_cli.get_timeline()
        elif opt in ('-p', '--post'):
            weibo_cli.post_status(arg)

if __name__ == '__main__':
    main()

import os
import time
import numpy as np
import yaqc
import toml
from pathlib import Path
from appdirs import user_config_dir

class SpectrographDriver:
    def __init__(self, config_path=None):
        self.config = self._load_configuration(config_path)
        self.ctrl = None
        self.max_gratings = self.config.get('max_gratings', 3)
        self.current_grating = None
        self.is_initialized = False
        self._connect_hardware()

    def _load_configuration(self, config_path=None):
        default_config_dir = Path(user_config_dir('spectrograph_driver'))
        default_config_path = default_config_dir / 'config.toml'

        if config_path is None:
            config_path = default_config_path

        if not os.path.exists(config_path):
            default_config = {
                'hardware_address': 'localhost:9000',
                'max_gratings': 3,
                'gratings': [
                    {'name': 'Low Resolution', 'lines_per_mm': 150},
                    {'name': 'Medium Resolution', 'lines_per_mm': 600},
                    {'name': 'High Resolution', 'lines_per_mm': 1200}
                ]
            }
            os.makedirs(default_config_dir, exist_ok=True)
            with open(config_path, 'w') as f:
                toml.dump(default_config, f)

        return toml.load(config_path)

    def _connect_hardware(self):
        try:
            address = self.config.get('hardware_address', 'localhost:9000')
            self.ctrl = yaqc.client(address)
        except Exception as e:
            print(f"Hardware connection failed: {e}")
            self.ctrl = None

    def initialize(self):
        if self.ctrl is None:
            raise RuntimeError("No hardware connection established")

        try:
            self.ctrl.reset()
            time.sleep(2)

            # Perform initial calibration
            self.ctrl.calibrate()
            self.current_grating = 0
            self.is_initialized = True
        except Exception as e:
            print(f"Initialization error: {e}")
            self.is_initialized = False

    def set_grating(self, grating_index):
        if not 0 <= grating_index < self.max_gratings:
            raise ValueError(f"Invalid grating index: {grating_index}")

        try:
            self.ctrl.set_turret(grating_index)
            self.current_grating = grating_index
            time.sleep(1)  # Allow mechanical transition
        except Exception as e:
            print(f"Grating change error: {e}")

    def set_wavelength(self, wavelength):
        if not self.is_initialized:
            raise RuntimeError("Device not initialized")

        try:
            self.ctrl.set_position(wavelength)
        except Exception as e:
            print(f"Wavelength setting error: {e}")

    def get_current_position(self):
        if not self.is_initialized:
            return None

        return self.ctrl.get_position()

    def is_busy(self):
        return self.ctrl.busy() if self.ctrl is not None else False

    def get_grating_info(self, grating_index=None):
        if grating_index is None:
            grating_index = self.current_grating

        gratings = self.config.get('gratings', [])
        return gratings[grating_index] if 0 <= grating_index < len(gratings) else None

    def perform_wavelength_scan(self, start_wavelength, end_wavelength, step_size):
        wavelengths = np.arange(start_wavelength, end_wavelength, step_size)
        scan_results = []

        for wavelength in wavelengths:
            if not self.is_initialized:
                break

            self.set_wavelength(wavelength)
            time.sleep(0.5)

            measurement = self.ctrl.measure()
            scan_results.append({
                'wavelength': wavelength,
                'intensity': measurement
            })

        return scan_results

    def close(self):
        if self.ctrl is not None:
            self.ctrl.close()
            self.is_initialized = False

import logging
import mysql.connector
from typing import Dict, Any, Optional
from db_operation import DBOperation

class ScalingRuleRetriever:
    def __init__(self, host: str, user: str, password: str, database: str):
        self._logger = logging.getLogger(__name__)
        self._connection_params = {
            'host': host,
            'user': user,
            'password': password,
            'database': database
        }
        self._connection = None
        self._cursor = None

    def _establish_connection(self) -> None:
        try:
            self._connection = mysql.connector.connect(**self._connection_params)
            self._cursor = self._connection.cursor(dictionary=True)
            self._logger.info("Database connection established successfully")
        except mysql.connector.Error as error:
            self._logger.error(f"Database connection error: {error}")
            raise

    def _close_connection(self) -> None:
        if self._cursor:
            self._cursor.close()
        if self._connection:
            self._connection.close()
        self._logger.info("Database connection closed")

    def query_configuration(self, marathon: str, app: str, resource_flags: Dict[str, bool]) -> Dict[str, Any]:
        try:
            self._establish_connection()
            result = {}

            if resource_flags.get('cpu', False):
                result['cpu_config'] = self._get_cpu_configuration(marathon, app)

            if resource_flags.get('memory', False):
                result['memory_config'] = self._get_memory_configuration(marathon, app)

            if resource_flags.get('thread', False):
                result['thread_config'] = self._get_thread_configuration(marathon, app)

            if resource_flags.get('request_queue', False):
                result['request_queue_config'] = self._get_request_queue_configuration(marathon, app)

            return result
        except Exception as e:
            self._logger.error(f"Configuration query error: {e}")
            raise
        finally:
            self._close_connection()

    def _get_cpu_configuration(self, marathon: str, app: str) -> Optional[Dict[str, Any]]:
        query = """
        SELECT threshold, scaling_factor, min_instances, max_instances
        FROM cpu_scaling_rules
        WHERE marathon_env = %s AND app_name = %s
        """
        self._cursor.execute(query, (marathon, app))
        return self._cursor.fetchone()

    def _get_memory_configuration(self, marathon: str, app: str) -> Optional[Dict[str, Any]]:
        query = """
        SELECT threshold, scaling_factor, min_instances, max_instances
        FROM memory_scaling_rules
        WHERE marathon_env = %s AND app_name = %s
        """
        self._cursor.execute(query, (marathon, app))
        return self._cursor.fetchone()

    def _get_thread_configuration(self, marathon: str, app: str) -> Optional[Dict[str, Any]]:
        query = """
        SELECT threshold, scaling_factor, min_instances, max_instances
        FROM thread_scaling_rules
        WHERE marathon_env = %s AND app_name = %s
        """
        self._cursor.execute(query, (marathon, app))
        return self._cursor.fetchone()

    def _get_request_queue_configuration(self, marathon: str, app: str) -> Optional[Dict[str, Any]]:
        query = """
        SELECT threshold, scaling_factor, min_instances, max_instances
        FROM request_queue_scaling_rules
        WHERE marathon_env = %s AND app_name = %s
        """
        self._cursor.execute(query, (marathon, app))
        return self._cursor.fetchone()

    def validate_configuration(self, config: Dict[str, Any]) -> bool:
        try:
            for key, value in config.items():
                if value is None:
                    self._logger.warning(f"Configuration missing for {key}")
                    return False
            return True
        except Exception as e:
            self._logger.error(f"Configuration validation error: {e}")
            return False

def main():
    logging.basicConfig(level=logging.INFO)

    db_retriever = ScalingRuleRetriever(
        host='localhost',
        user='scaling_service',
        password='secret_password',
        database='scaling_config_db'
    )

    resource_flags = {
        'cpu': True,
        'memory': True,
        'thread': False,
        'request_queue': True
    }

    try:
        config = db_retriever.query_configuration('production', 'webservice', resource_flags)
        if db_retriever.validate_configuration(config):
            print("Scaling configuration retrieved successfully")
    except Exception as e:
        print(f"Error retrieving configuration: {e}")

if __name__ == '__main__':
    main()

