import docker
import logging
from functools import wraps

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

RESERVED_METHODS = ['__init__', '__repr__', '__getattribute__', 'running', 'start', 'stop']

class Container:
    def __init__(self, container_obj):
        self._container = container_obj
        self._id = container_obj.id
        self._name = container_obj.name

    @property
    def name(self):
        return self._name

    @property
    def id(self):
        return self._id

    def __repr__(self):
        return f"Container({self._name})"

class Image:
    def __init__(self, image_obj):
        self._image = image_obj
        self._id = image_obj.id
        self._tags = image_obj.tags

    @property
    def tags(self):
        return self._tags

    def __repr__(self):
        return f"Image({self._tags[0] if self._tags else 'Untagged'})"

def handle_docker_errors(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except docker.errors.DockerException as e:
            logger.error(f"Docker operation failed: {e}")
            raise
    return wrapper

class Dock:
    def __init__(self, base_url='unix://var/run/docker.sock'):
        try:
            self._client = docker.from_env(base_url=base_url)
        except Exception as e:
            logger.error(f"Failed to initialize Docker client: {e}")
            raise

    def __repr__(self):
        return f"Dock(containers={len(self.containers)})"

    def __getattribute__(self, name):
        try:
            return object.__getattribute__(self, name)
        except AttributeError:
            if name in RESERVED_METHODS:
                raise

            try:
                return getattr(self._client, name)
            except AttributeError:
                raise AttributeError(f"'{self.__class__.__name__}' object has no attribute '{name}'")

    @property
    def containers(self):
        return [Container(container) for container in self._client.containers.list()]

    @property
    def images(self):
        return [Image(image) for image in self._client.images.list()]

    @handle_docker_errors
    def start(self, container):
        if isinstance(container, basestring):
            container = self._client.containers.get(container)
        elif isinstance(container, Container):
            container = container._container

        container.start()
        return Container(container)

    @handle_docker_errors
    def stop(self, container, timeout=None):
        if isinstance(container, basestring):
            container = self._client.containers.get(container)
        elif isinstance(container, Container):
            container = container._container

        container.stop(timeout=timeout)
        return Container(container)

    @property
    def running(self):
        return [Container(container) for container in self._client.containers.list(filters={'status': 'running'})]

    @property
    def system_info(self):
        return {
            'version': self._client.version(),
            'info': self._client.info(),
            'df': self._client.df()
        }

    def pull(self, image, tag='latest'):
        return Image(self._client.images.pull(image, tag=tag))

    def create_container(self, image, **kwargs):
        container = self._client.containers.create(image, **kwargs)
        return Container(container)

import csv
import numpy as np
import matplotlib.pyplot as plt
from scipy import stats
from scipy.optimize import curve_fit

def countKey(listDataDicts, key):
    return sum(1 for d in listDataDicts if d.get(key))

def avgUse30Days(listDataDicts, key):
    validEntries = [int(d[key]) for d in listDataDicts if d.get(key) and int(d[key]) < 900]
    return np.mean(validEntries) if validEntries else 0

def avgUse30DaysWithZeros(listDataDicts, key):
    entries = [int(d[key]) if d.get(key) and int(d[key]) < 900 else 0 for d in listDataDicts]
    return np.mean(entries)

def powerLaw(x, a, b):
    return a * np.power(x, b)

def expDecay(x, a, b, c):
    return a * np.exp(-b * x) + c

def loadDrugData(filename):
    listDataDicts = []
    with open(filename, 'r') as tsvfile:
        reader = csv.DictReader(tsvfile, delimiter='\t')
        for row in reader:
            listDataDicts.append(row)
    return listDataDicts

def analyzeSubstanceCorrelation(listDataDicts, substance):
    ageFirstUseKey = f'age_first_{substance}'
    useLast30Key = f'use_last_30_days_{substance}'

    validData = [
        (int(d[ageFirstUseKey]), int(d[useLast30Key])) 
        for d in listDataDicts 
        if d.get(ageFirstUseKey) and d.get(useLast30Key)
        and int(d[ageFirstUseKey]) < 900 
        and int(d[useLast30Key]) < 900
    ]

    if not validData:
        return None

    xdata, ydata = zip(*validData)
    xdata = np.array(xdata)
    ydata = np.array(ydata)

    slope, intercept, r_value, p_value, std_err = stats.linregress(xdata, ydata)

    try:
        popt_power, _ = curve_fit(powerLaw, xdata, ydata)
        popt_exp, _ = curve_fit(expDecay, xdata, ydata)
    except RuntimeError:
        popt_power = popt_exp = None

    plt.figure(figsize=(10, 6))
    plt.scatter(xdata, ydata, alpha=0.5)
    plt.plot(xdata, slope * xdata + intercept, color='red', label='Linear Regression')

    if popt_power is not None:
        plt.plot(xdata, powerLaw(xdata, *popt_power), color='green', label='Power Law Fit')

    if popt_exp is not None:
        plt.plot(xdata, expDecay(xdata, *popt_exp), color='blue', label='Exponential Decay Fit')

    plt.title(f'{substance.capitalize()} Use Analysis')
    plt.xlabel('Age of First Use')
    plt.ylabel('Frequency of Use in Last 30 Days')
    plt.legend()

    return {
        'slope': slope,
        'intercept': intercept,
        'r_squared': r_value**2,
        'p_value': p_value,
        'standard_error': std_err,
        'power_law_params': popt_power,
        'exp_decay_params': popt_exp
    }

def main():
    drugData = loadDrugData('drug_use_survey.tsv')
    substances = ['marijuana', 'cocaine', 'heroin', 'methamphetamine']

    results = {}
    for substance in substances:
        result = analyzeSubstanceCorrelation(drugData, substance)
        if result:
            results[substance] = result
            plt.show()

    print("Analysis Results:", results)

if __name__ == '__main__':
    main()

